/// <summary>
/// find method for records with provided client RefRecId
/// </summary>
/// <param name = "_clientsRefRecId">AVAAllianceClientsRefRecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXSNClientGroup2Client</returns>
public static NDXSNClientGroup2Client findClientsRecId(AVAAllianceClientsRefRecId _clientsRefRecId, boolean _selectForUpdate = false)
{
    NDXSNClientGroup2Client cG2CRecord;

    if(_selectForUpdate)
    {
        cG2CRecord.selectForUpdate(_selectForUpdate);
    }

    select firstonly cG2CRecord
        where cG2CRecord.RefRecId_Client == _clientsRefRecId;

    return cG2CRecord;
}

/// <summary>
/// find method for records with provided client group RefRecId
/// </summary>
/// <param name = "_clientGroupRefRecId">AVAAllianceClientGroupRefRecId</param>
/// <param name = "_clientsRefRecId">AVAAllianceClientsRefRecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXSNClientGroup2Client</returns>
public static NDXSNClientGroup2Client find(AVAAllianceClientGroupRefRecId _clientGroupRefRecId, AVAAllianceClientsRefRecId _clientsRefRecId, boolean _selectForUpdate = false)
{
    NDXSNClientGroup2Client cG2CRecord;

    if(_selectForUpdate)
    {
        cG2CRecord.selectForUpdate(_selectForUpdate);
    }

    select firstonly cG2CRecord
        where cG2CRecord.RefRecId_ClientGroup == _clientGroupRefRecId
            && cG2CRecord.RefRecId_Client == _clientsRefRecId;

    return cG2CRecord;
}

/// <summary>
/// checks if record exists for provided input
/// </summary>
/// <param name = "_clientGroupRefRecId">AVAAllianceClientGroupRefRecId</param>
/// <param name = "_clientsRefRecId">AVAAllianceClientsRefRecId</param>
/// <returns>boolean</returns>
public static boolean existsRecord(AVAAllianceClientGroupRefRecId _clientGroupRefRecId, AVAAllianceClientsRefRecId _clientsRefRecId)
{
    return NDXSNClientGroup2Client::find(_clientGroupRefRecId, _clientsRefRecId).RecId;
}

/// <summary>
/// checks if record exists for provided input
/// </summary>
/// <param name = "_clientGroupRefRecId">AVAAllianceClientGroupRefRecId</param>
/// <returns>boolean</returns>
public static boolean existsClientGroup(AVAAllianceClientGroupRefRecId _clientGroupRefRecId)
{
    NDXSNClientGroup2Client locCG2C;

    select firstonly locCG2C
        where locCG2C.RefRecId_ClientGroup == _clientGroupRefRecId;

    return locCG2C.RecId;
}
